sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    try {

        var obRApi = new sn_ws.RESTMessageV2('WeatherAPI1', 'Default GET');
        obRApi.setStringParameterNoEscape('zipVal', current.u_string_1);

        var response = obRApi.execute();
        var responseBody = response.getBody();
        var httpstatus = response.getStatusCode();

        gs.info("Http Status code = " + httpstatus);
        gs.info("Response Body = " + responseBody);

        if (httpstatus == '200') {

            //convert response JSON to JS object
            var respObj = JSON.parse(responseBody);
            gs.info("reponse from JSON call = " + respObj.location.tz_id);

            var apiTZID = respObj.location.tz_id;
            var apiTempF = respObj.current.temp_f;

            // if (JSUtil.notNil(current.parent)){
            //	var gr = new GlideREcord('x_58872_needit_needit');
            //	gr.addQuery('sys_id',current.parent);	
            //	gr.query();
            //	if(gr.next()) {
            //		gr.u_string_2 = apiTZID;
            //		gr.u_integer_3 = apiTempF;
            //		gr.update();
            //	}
            //*}
            current.setValue('u_string_2', apiTZID);
            current.setValue('u_integer_3', apiTempF);
            current.update();
        } else {
            gs.error('Error calling API: ' + httpstatus + ' - ' + responseBody);
        }
    } catch (ex) {
        var message = ex.message;
    }

})(current, previous);
